package com.campusmart.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="products",indexes={@Index(name="idx_product_category",columnList="category_id"),@Index(name="idx_product_name",columnList="name")}) public class Product{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(nullable=false,length=2000)private String description;@ManyToOne(optional=false)private Category category;@Column(nullable=false,precision=12,scale=2)private BigDecimal price;@Enumerated(EnumType.STRING)@Column(nullable=false)private Condition condition;@Enumerated(EnumType.STRING)@Column(nullable=false)private ProductType productType;private String imageUrl;private String location;@ManyToOne(optional=false)private User seller;@Column(nullable=false)private boolean available=true;private LocalDateTime createdAt=LocalDateTime.now();public enum Condition{NEW,LIKE_NEW,GOOD,FAIR}public enum ProductType{SELL,EXCHANGE,DONATE}public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Category getCategory(){return category;}public void setCategory(Category v){category=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public Condition getCondition(){return condition;}public void setCondition(Condition v){condition=v;}public ProductType getProductType(){return productType;}public void setProductType(ProductType v){productType=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public User getSeller(){return seller;}public void setSeller(User v){seller=v;}public boolean isAvailable(){return available;}public void setAvailable(boolean v){available=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
